/**
 * 引擎配置（App 侧构造一次，进程内单例）。
 */
public struct MobileConfig {
    /**
     * 数据目录（App 私有沙箱路径，如 filesDir/nylon）。
     */
    public var dataDir: String
    /**
     * 记忆归属者 ID（单用户 App 固定一个即可；多账号切换时换 owner）。
     */
    public var owner: String
    /**
     * 端上 ONNX 嵌入模型路径（可选；与 embed_vocab_path 成对提供）。
     * 注意：启用后 dims 由模型决定，与存量不同维度的库不兼容——换模型需重建记忆库。
     */
    public var embedModelPath: String?
    /**
     * WordPiece 词表 vocab.txt 路径（随模型分发）。
     */
    public var embedVocabPath: String?
    /**
     * 自动 checkpoint 写阈值：累计 N 次 weave 后自动落盘（None=默认 32，Some(0)=关闭）。
     * 端上进程可能随时被杀，该阈值决定 WAL 重放时长与崩溃恢复成本的上界。
     */
    public var autoCheckpointWrites: UInt32?
    /**
     * 自动 checkpoint 时间阈值：距上次落盘超过 T 秒且有脏写即触发（None=默认 300，Some(0)=每次写后都触发）。
     */
    public var autoCheckpointSecs: UInt64?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * 数据目录（App 私有沙箱路径，如 filesDir/nylon）。
         */dataDir: String, 
        /**
         * 记忆归属者 ID（单用户 App 固定一个即可；多账号切换时换 owner）。
         */owner: String, 
        /**
         * 端上 ONNX 嵌入模型路径（可选；与 embed_vocab_path 成对提供）。
         * 注意：启用后 dims 由模型决定，与存量不同维度的库不兼容——换模型需重建记忆库。
         */embedModelPath: String?, 
        /**
         * WordPiece 词表 vocab.txt 路径（随模型分发）。
         */embedVocabPath: String?, 
        /**
         * 自动 checkpoint 写阈值：累计 N 次 weave 后自动落盘（None=默认 32，Some(0)=关闭）。
         * 端上进程可能随时被杀，该阈值决定 WAL 重放时长与崩溃恢复成本的上界。
         */autoCheckpointWrites: UInt32?, 
        /**
         * 自动 checkpoint 时间阈值：距上次落盘超过 T 秒且有脏写即触发（None=默认 300，Some(0)=每次写后都触发）。
         */autoCheckpointSecs: UInt64?) {
        self.dataDir = dataDir
        self.owner = owner
        self.embedModelPath = embedModelPath
        self.embedVocabPath = embedVocabPath
        self.autoCheckpointWrites = autoCheckpointWrites
        self.autoCheckpointSecs = autoCheckpointSecs
    }
}

